```go
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"

	"github.com/golang/protobuf/proto"
)

// GenerateAvroSchema takes a filename and a struct name from the file.
func GenerateAvroSchema(filename string, structName string) error {
	file, err := parser.ParseFile(token.NewFileSet(), filename, nil, 0)
	if err != nil {
		return fmt.Errorf("error parsing file: %w", err)
	}

	structType, ok := file.Lists[0].(*ast.StructType)
	if !ok {
		return fmt.Errorf("the first element must be a StructType")
	}

	var fields []proto.Message

	for _, field := range structType.Fields {
		fieldName := proto.String(field.Names[0])
		fieldType := proto.String(fmt.Sprintf("%T", field.Type))

		fields = append(fields, &Field{FieldName: fieldName, FieldType: fieldType})
	}

	schema := &Schema{
		Name:    proto.String(structName),
		Fields:  fields,
		Version: proto.Int32(1), // Version can be changed if needed
	}

	err = ioutil.WriteFile("struct.avsc", proto.Marshal(schema), 0644)
	if err != nil {
		return fmt.Errorf("error writing Avro schema: %w", err)
	}

	fmt.Println("Avro schema generated successfully!")
	return nil
}

type Field struct {
	FieldName *string
	FieldType *string
}

type Schema struct {
	Name       *string
	Version    int32
	Fields     []*Field
}

func main() {
	if len(os.Args) < 3 {
		fmt.Println("Usage: go run main.go <filename> <struct_name>")
		os.Exit(1)
	}

	filename := os.Args[1]
	structName := os.Args[2]

	err := GenerateAvroSchema(filename, structName)
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
	}
}
```

